package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/ledgers/{ledgerId}/balance-snapshots") public class BalanceSnapshotController{private final BalanceSnapshotService service;public BalanceSnapshotController(BalanceSnapshotService s){service=s;}@PostMapping public Mono<BalanceSnapshotView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateBalanceSnapshotRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<BalanceSnapshotView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}}
